CREATE TABLE IF NOT EXISTS concepts (id UUID PRIMARY KEY, key TEXT UNIQUE NOT NULL, name TEXT NOT NULL, domain TEXT, description TEXT); CREATE TABLE IF NOT EXISTS prerequisites (concept_id UUID, prerequisite_id UUID, weight REAL DEFAULT 1, PRIMARY KEY(concept_id,prerequisite_id)); CREATE TABLE IF NOT EXISTS concept_relationships (source_id UUID, target_id UUID, relation TEXT, weight REAL DEFAULT 1, PRIMARY KEY(source_id,target_id,relation));
